(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0024.js"] = [{"id":"glyph-seal-76c6","script":"seal","character":"盆","reading":"pén","description":"pén：(1)盛放东西或洗涤的用具～景。～花。～栽。脸～。澡～。\n(2)中央凹入像盆状的东西～地。骨～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盆"},{"id":"glyph-seal-76c8","script":"seal","character":"盈","reading":"yíng","description":"yíng：(1)充满～满。～溢。充～。沸反～天。\n(2)多余～余。～亏。～利。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盈"},{"id":"glyph-seal-76c9","script":"seal","character":"盉","reading":"hé","description":"古代用来调和酒水的器具，多为青铜制品。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-76ca","script":"seal","character":"益","reading":"yì","description":"yì：(1)增加～寿延年。增～。损～。\n(2)好处，有好处利～。～处。公～。权～。受～非浅。\n(3)更加～发。日～壮大。\n(4)古同溢”，水漫出来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-益"},{"id":"glyph-seal-76ce","script":"seal","character":"盎","reading":"àng","description":"àng：(1)古代的一种盆，腹大口小。\n(2)盛（shèng），充盈春意～然。诗意～然。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盎"},{"id":"glyph-seal-76d0","script":"seal","character":"盐","reading":"yán","description":"由金属\n⒈盐，又叫\"咸～\" ，主要化学成份是氯化钠。放在食品里使有咸味加碘食～。\n⒉盐类，化学上的中性化合物。它是酸类中的氢根被金属元素置换而成。\n盐yàn 1.用盐腌物。 2.指海水﹑盐水等淹﹑浸。 3.通\"艳\"。羡慕。 4.通\"艳\"。美好。 5.古乐曲名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盐"},{"id":"glyph-seal-76d1","script":"seal","character":"监","reading":"jiān","description":"以监其上下之所好。”\n王怒,\n⒈察看，督察，从上看下～督。～察。～观四方。\n⒉牢，狱～牢。～狱。坐～房。\n监kàn 1.地名用字。参见\"监乡\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-监"},{"id":"glyph-seal-76d6","script":"seal","character":"盖","reading":"gài","description":"苫,用茅草编成的遮盖物,可以蔽体或覆屋顶\n雨伞\n车篷\n庭有枇杷\n⒈遮蔽器物的东西茶杯～。瓶～子。锅～儿。\n⒉〈古〉遮阳遮雨的用具华～。\n⒊遮掩，蒙上覆～。～住。～被子。\n⒋建筑～房子。～高楼。\n⒌打上～手印。～公章。\n⒍压倒，超过，没有人比得上气～山河。功～五帝。～世英雄。\n⒎动物的甲壳龟～。蟹～。\n⒏文言虚词。\n①发语词～闻。\n②大概～近年之事。\n③连词。〈表〉原因为何不知，～未学也。\n⒐〈古〉通\"盍\"∥不。\n⒑见gě。\n⒈姓。\n⒉见gài。\n盖hé 1.通\"盍\"∥不。 2.通\"盍\"∥。 3.通\"阖\"。门扇。\n盖hài 1.桅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盖"},{"id":"glyph-seal-76d7","script":"seal","character":"盗","reading":"dào","description":"dào：(1)偷窃，用不正当的手段营私或谋取～窃。～贼。～伐。～掘。～运。～卖。～用。～名欺世（亦称欺世盗名”）。\n(2)偷窃或抢劫财物的人海～。强～。窃国大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盗"},{"id":"glyph-seal-76d8","script":"seal","character":"盘","reading":"pán","description":"古代的一种盥洗用具\n形状或功用像盘子的东西\n⒉形状或功用像盘子的脸～儿。算～。轮～。磨～。棋～。\n⒊回绕，弯曲～旋。～香。～膝。～山道。\n⒋垒，砌～灶。～炕。\n⒍指市场上成交的价格开～。收～。平～儿。\n⒎量词下完了两～棋。买回了三～录像带。\n盘xuán 1.漩涡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盘"},{"id":"glyph-seal-76db","script":"seal","character":"盛","reading":"shèng；chéng","description":"shèng：(1)兴旺兴～。繁～。旺～。～世。～衰。茂～。全～时期。\n(2)炽烈年轻气～。～怒。～气凌人。\n(3)丰富，华美～产。～宴。～装。\n(4)热烈，规模大～大。～况。～典。～举。\n(5)广泛，程度深～传（chuán）。～行（xíng）。～赞。～名。～夏。\n(6)深厚～意。\n(7)姓。\n衰；\nchéng：(1)把东西放进去～饭。\n(2)容纳～器。小桶～不下多少东西。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盛"},{"id":"glyph-seal-76df","script":"seal","character":"盟","reading":"méng","description":"méng：(1)旧时指宣誓缔约，现指阶级的联合，国与国的联合～军。～友。同～国。～约。山～海誓。\n(2)指结拜弟兄～兄。～弟。\n(3)中国内蒙古自治区的行政单位。\n(4)发（誓）～誓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盟"},{"id":"glyph-seal-76e5","script":"seal","character":"盥","reading":"guàn","description":"guàn：(1)浇水洗手，泛指洗～洗。～漱。\n(2)洗手器皿承姑奉～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盥"},{"id":"glyph-seal-76ee","script":"seal","character":"目","reading":"mù","description":"mù：(1)眼睛～光。醒～。历历在～。～指气使（用眼光和气色示意以役使别人，形容骄横傲慢的神志。亦作颐指气使”）。\n(2)看，视～语。～论（喻没有自知之明或浅陋狭隘的见解）。\n(3)想要达到的地点、境地或想要得到的结果～的（dì）（亦指箭靶的中心）。\n(4)大项中再分的小项条～。纲举～张。\n(5)名称数～。巧立名～。\n(6)标题～录。\n(7)生物学分类系统上所用的等级之一，在纲”以下，科”以上鸟纲中有雁形～和鸡形～。\n(8)孔眼网～。\n(9)指为首的人头～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-目"},{"id":"glyph-seal-76f1","script":"seal","character":"盱","reading":"xū","description":"xū：张目～～（张目直视）。～衡（举眉扬目。多用于对政治局势的观察，如～～大局”、～～中外”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盱"},{"id":"glyph-seal-76f2","script":"seal","character":"盲","reading":"máng","description":"máng：瞎，看不见东西，对事物不能辨认～从。～动。～目。～人。～区（指雷达、探照灯、胃镜等探测或观察不到的区域）。～流。～人瞎马（喻处境非常危险）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盲"},{"id":"glyph-seal-76f4","script":"seal","character":"直","reading":"zhí","description":"zhí：(1)不弯曲～线。～角。～径。～立。～截了当。～觉（jué）。～观。\n(2)把弯曲的伸开～起腰来。\n(3)公正合理是非曲～。理～气壮。耿～。正～。\n(4)爽快，坦率～爽。～率（shuài）。～谏。～诚。～言不讳。\n(5)一个劲儿地，连续不断一～走。～哭。\n(6)竖，与横”相对不要横着写，要～着写。\n(7)汉字笔形之一，自上至下。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-直"},{"id":"glyph-seal-76f8","script":"seal","character":"相","reading":"xiāng；xiàng","description":"xiāng：互相；表示对对方的行为。xiàng：相貌、形态；观察察看；古代辅佐君主的官职。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-76fc","script":"seal","character":"盼","reading":"pàn","description":"pàn：(1)希望，想望～望。切～。\n(2)看，引申为看待流～。左顾右～。\n(3)眼睛白黑分明～倩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盼"},{"id":"glyph-seal-76fe","script":"seal","character":"盾","reading":"dùn","description":"dùn：(1)古代打仗时防护身体，挡住敌人刀箭等的牌～牌（亦喻推托的借口）◇～。\n(2)盾形的东西（多指硬币上的纹章）金～。银～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盾"},{"id":"glyph-seal-7701","script":"seal","character":"省","reading":"shěng；xǐng","description":"shěng：节约，减免；行政区划名。xǐng：反省、察看；醒悟，如自省、省亲、不省人事。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7704","script":"seal","character":"眄","reading":"miǎn；miàn","description":"miàn：斜着眼看～视。～睨。～伺（窥伺）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眄"},{"id":"glyph-seal-7707","script":"seal","character":"眇","reading":"miǎo","description":"miǎo：(1)瞎了一只眼，后亦指两眼俱瞎～视（ａ．用一只眼看；ｂ．轻视）。生而～者不识日”。\n(2)细小，微小～小。～～（ａ．微小，如～～之身”；ｂ．边远，高远，如路～～之默默”；ｃ．远看，如目～～兮愁予”）。～身（微小之身，古代帝王自称）。\n(3)古同渺”，远，高。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眇"},{"id":"glyph-seal-7708","script":"seal","character":"眈","reading":"dān","description":"dān：(1)注视虎视～～（凶狠贪婪地看着）。\n(2)古同耽”，沉溺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眈"},{"id":"glyph-seal-7709","script":"seal","character":"眉","reading":"méi","description":"méi：(1)眼上额下的毛～毛。～宇（两眉上面的地方）。～心。～目。～寿（长寿）。～睫。扬～吐气。\n(2)书页上端的空白书～。～批。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眉"},{"id":"glyph-seal-770a","script":"seal","character":"眊","reading":"mèi；mào","description":"⒈眼睛失神，看不清楚。\n⒉（〈古〉也写作\"耄\"）年老。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眊"},{"id":"glyph-seal-770b","script":"seal","character":"看","reading":"kàn；kān","description":"kàn：(1)使视线接触人或物～见。～书。～齐。\n(2)观察，判断～病。观～。～好（根据市场情况，估计某种商品好销）。～透（透彻深刻地了解或认识。亦称看破”、看穿”）。～风使舵。\n(3)访问，拜望～望。～朋友。\n(4)照应，对待～重（zhòng）。～轻。～待。\n(5)想，以为～法。\n(6)先试试以观察它的结果做做～。\n(7)提防，小心别跑，～摔着。\n(8)安排～茶。～酒。～座。\n瞅；顾；观；瞥；瞧；视；望；\nkān：守护，监视～护。～押。～门。～青（看守正在结实还未成熟的庄稼）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-看"},{"id":"glyph-seal-7719","script":"seal","character":"眙","reading":"yí；chì","description":"yí：〔盱～〕地名，在中国江苏省。\nchì：直视，瞪目～不禁”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眙"},{"id":"glyph-seal-771f","script":"seal","character":"真","reading":"zhēn","description":"zhēn：(1)与客观事实相符合，与假”、伪”相对～诚。～谛。～挚。～心。逼～。认～。～才实学。～知灼见。\n(2)确实，的确～好。～正。～切。\n(3)清楚，显明看得～。咬字很～。\n(4)本性，本原纯～。天～。\n(5)人的肖像传（chuán）～。写～。\n(6)汉字的楷书～字。～书。～草隶篆。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-真"},{"id":"glyph-seal-7726","script":"seal","character":"眦","reading":"zì","description":"zì：眼角，上下眼睑的接合处，靠近鼻子的称内眦”，靠近两鬓的称外眦”～裂（形容愤怒到极点）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眦"},{"id":"glyph-seal-7728","script":"seal","character":"眨","reading":"zhǎ","description":"zhǎ：眼睛很快地一闭一开～眼。一～眼（形容时间短）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眨"},{"id":"glyph-seal-7729","script":"seal","character":"眩","reading":"xuàn","description":"xuàn：(1)眼睛昏花看不清楚～晕。～瞀。头昏目～。\n(2)迷惑，迷乱～于名利。～惑。\n(3)古同炫”，炫耀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眩"},{"id":"glyph-seal-772d","script":"seal","character":"眭","reading":"suī；guì","description":"guì：目光深注的样子～然能视”。\nsuī：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眭"},{"id":"glyph-seal-772f","script":"seal","character":"眯","reading":"mī；mí","description":"mī：(1)眼皮微微合拢～缝双目。笑～了眼。\n(2)小睡～一会儿。\nmí：尘土入眼，不能睁开看东西让沙子～了眼睛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眯"},{"id":"glyph-seal-7735","script":"seal","character":"眵","reading":"chī","description":"chī：眼睛分泌出来的液体凝结成的淡黄色的东西。俗称眼屎”，亦称眵目糊（hū）”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眵"},{"id":"glyph-seal-7737","script":"seal","character":"眷","reading":"juàn","description":"juàn：(1)顾念，爱恋～念。～恋。～顾。～注（爱护关注）。～～（依恋的样子）。\n(2)亲属亲～。女～。～属。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眷"},{"id":"glyph-seal-7738","script":"seal","character":"眸","reading":"móu","description":"móu：眼中瞳人，泛指眼睛～子。凝～远望。明～皓齿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眸"},{"id":"glyph-seal-773a","script":"seal","character":"眺","reading":"tiào","description":"tiào：(1)望，往远处看～览。～瞩。～望。远～。\n(2)目不正，斜视。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眺"},{"id":"glyph-seal-773c","script":"seal","character":"眼","reading":"yǎn","description":"yǎn：(1)人和动物的视觉器官～睛。～底。～力。～色。～神。～帘。～目。～疾手快。\n(2)见识，对事物的看法～光远大。～界开阔。\n(3)孔洞，窟窿炮～。针～儿。泉～。\n(4)关节，要点节骨～儿。字～儿。\n(5)戏曲中的节拍一板三～。\n(6)当前～前利益。～下。\n(7)量词一～井。\n(8)围棋术语，一方子中所留的空儿，在这个空儿中对方不能下成活棋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眼"},{"id":"glyph-seal-7747","script":"seal","character":"睇","reading":"dì","description":"dì：斜着眼看，看～望。～好。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睇"},{"id":"glyph-seal-7750","script":"seal","character":"睐","reading":"lài","description":"瞳仁不正\n旁视,斜视\n眺望","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睐"},{"id":"glyph-seal-7751","script":"seal","character":"睑","reading":"jiǎn","description":"眼皮,能够活动的眼皮盖\n唐时南诏人称州为睑\n睑板\n睑裂\n睑下垂\n睑炎","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睑"},{"id":"glyph-seal-775a","script":"seal","character":"睚","reading":"yá","description":"yá：眼角～眦（发怒时瞪眼睛，借指极小的仇恨）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睚"},{"id":"glyph-seal-7761","script":"seal","character":"睡","reading":"shuì","description":"shuì：闭目安息，大脑皮质处于休息状态～意。～觉。～梦。～眠。入～。～魔（喻强烈的睡意）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睡"},{"id":"glyph-seal-7762","script":"seal","character":"睢","reading":"suī","description":"suī：(1)仰视～盱（仰视）。～～（仰视的样子）。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睢"},{"id":"glyph-seal-7763","script":"seal","character":"督","reading":"dū","description":"dū：(1)察看；监管监～。～办。～导。～察。～促。～师。～率（shuài）（亦作督帅”）。～战。～学。\n(2)责罚～过（督察责备）。～责。\n(3)古代将官名都～。～邮。～护。总～。提～。～抚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-督"},{"id":"glyph-seal-7766","script":"seal","character":"睦","reading":"mù","description":"mù：(1)和好，亲近和～。～邻。兄弟不～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睦"},{"id":"glyph-seal-7768","script":"seal","character":"睨","reading":"nì","description":"nì：(1)斜着眼睛看～视。睥～。\n(2)偏斜日方中方～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睨"},{"id":"glyph-seal-7779","script":"seal","character":"睹","reading":"dǔ","description":"dǔ：看见目～。先～为快。耳闻目～。熟视无～。有目共～。～物思人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睹"},{"id":"glyph-seal-777d","script":"seal","character":"睽","reading":"kuí","description":"kuí：(1)不顺，乖离～孤（乖离而独处）。～异（意见不合）。\n(2)孤独。\n(3)同暌”。\n〔～～〕张大眼睛注视的样子，如众目～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睽"},{"id":"glyph-seal-777f","script":"seal","character":"睿","reading":"ruì","description":"ruì：(1)深明，通达～智。～哲（明智，英明）。\n(2)古代颂扬帝王用语～旨。～览（御览）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睿"},{"id":"glyph-seal-7780","script":"seal","character":"瞀","reading":"mào","description":"mào：(1)目眩，眼花～病（头目晕眩的病症）。～～（垂目下视的样子；形容眼睛昏花，引申为昏昏沉沉）。～瘛（中医指看不清，手脚拘挛的症状）。雀（qiǎo）～（古时称夜盲症）。\n(2)心绪紊乱。～乱。\n(3)愚昧世俗之沟犹～儒”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞀"},{"id":"glyph-seal-778b","script":"seal","character":"瞋","reading":"tián；chēn","description":"chēn：(1)睁大眼睛瞪人～目叱之。\n(2)同嗔”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞋"},{"id":"glyph-seal-7791","script":"seal","character":"瞑","reading":"míng","description":"míng：闭眼～目（亦指人死时心里无牵挂）。死不～目。\n〔～～〕形容昏花迷离。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞑"},{"id":"glyph-seal-7792","script":"seal","character":"瞒","reading":"mán","description":"通满”\n通颟”\n隐藏实情\n瞒mén 1.惭愧。参见\"瞒然\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞒"},{"id":"glyph-seal-779f","script":"seal","character":"瞟","reading":"piǎo","description":"piǎo：斜着眼睛看用眼～他。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞟"},{"id":"glyph-seal-77a2","script":"seal","character":"瞢","reading":"méng；měng","description":"méng：目不明目光～然。\nměng：同懵”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞢"},{"id":"glyph-seal-77a5","script":"seal","character":"瞥","reading":"piē","description":"piē：短时间地大略看看～见。～了一眼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞥"},{"id":"glyph-seal-77bb","script":"seal","character":"瞻","reading":"zhān","description":"zhān：往上或往前看～仰。～望。～拜。～谒。～念。～前顾后。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞻"},{"id":"glyph-seal-77bd","script":"seal","character":"瞽","reading":"gǔ","description":"gǔ：(1)盲人，瞎子离娄微睇兮，～以为无明。”\n(2)瞎～者。\n(3)古代乐师。\n(4)不达事理；没有见识；弃老取少谓之～。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞽"},{"id":"glyph-seal-77bf","script":"seal","character":"瞿","reading":"qú；jù；jv","description":"qú：(1)古代戟一类的兵器。\n(2)姓。\n〔～聃〕佛陀与老子，为佛”、道”两教宗奉的教主。\n〔～昙〕佛教创始人释迦牟尼，姓瞿昙◇以瞿昙为佛的代称，亦称乔达摩”。\njù：惊视，惊恐四顾～～（ａ．惊顾的样子；ｂ．迅速张望的样子；ｃ．勤谨的样子）。～然。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞿"},{"id":"glyph-seal-77cd","script":"seal","character":"矍","reading":"jué","description":"jué：惊慌地看着～然（惊视的样子）。～～（左右惊顾的样子）。\n〔～铄〕形容年老而有精神的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矍"},{"id":"glyph-seal-77db","script":"seal","character":"矛","reading":"máo","description":"máo：古代用来刺杀敌人的长柄兵器～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矛"},{"id":"glyph-seal-77dc","script":"seal","character":"矜","reading":"jīn；qín；guān","description":"jīn：(1)怜悯，怜惜～悯（怜悯）。～惜。～恤。\n(2)自尊，自大，自夸～夸。～伐。～恃。骄～。\n(3)庄重，拘谨～持。～重（zhòng）。\nqín：矛柄。\nguān：古同鳏”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矜"},{"id":"glyph-seal-77e2","script":"seal","character":"矢","reading":"shǐ","description":"shǐ：(1)箭流～。弓～。有的（dì）放～。～镞。\n(2)誓～志不渝（发誓立志，永不改变）。\n(3)正直～言（正直的言论）。\n(4)陈列公～鱼于棠”。\n(5)施布～其文德”。\n(6)古代投壶（一种娱乐活动）用的筹。\n(7)古同屎”，粪便。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矢"},{"id":"glyph-seal-77e3","script":"seal","character":"矣","reading":"yǐ","description":"yǐ：文言助词（ａ．用于句末，与了”相同，如由来久～”，悔之晚～”；ｂ．表示感叹，如大～哉”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矣"},{"id":"glyph-seal-77e5","script":"seal","character":"知","reading":"zhī；zhì","description":"zhī：(1)晓得，明了～道。～名（著名）。～觉（有感觉而知道）。良～。～人善任。温故～新。～难而进。～情达理。\n(2)使知道通～。～照。\n(3)学识，学问～识，求～。无～。\n(4)主管～县（旧时的县长）。～府。～州。～宾（指主管招待宾客的人。亦称知客”）。\n(5)彼此了解相～。～音。～近。\n(6)彼此了解、交好的人故～（老朋友）。\nzhì：古同智”，智慧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-知"},{"id":"glyph-seal-77e9","script":"seal","character":"矩","reading":"jǔ；jv","description":"jǔ：(1)画直角或方形的工具～尺（曲尺）。～形（长方形）。力～（物理学上指使物体转动的力乘以到转轴的距离）。规～。\n(2)法则，规则循规蹈～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矩"},{"id":"glyph-seal-77eb","script":"seal","character":"矫","reading":"jiǎo","description":"凡事别矫情\n矫〈动〉\n把弯曲的物体弄直\n匡正;纠正\n以身矫之。\n⒈将弯曲的东西弄直～正曲木。〈引〉纠正～枉过正。～正了偏差。\n⒉假托，诈称～令。\n⒊强，勇武～健的步伐。～捷。\n矫jiāo 1.古代投壶，箭从壶中跃出而手接之复投谓之\"矫\"。也称为\"骁\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矫"},{"id":"glyph-seal-77ed","script":"seal","character":"短","reading":"duǎn","description":"duǎn：(1)长度小，与长（cháng）”相对～期。～暂。～促。～途。～命。～讯。～浅。～兵相接。～小精悍。\n(2)缺少，欠～少。～缺。\n(3)缺点～处。护～。取长补～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-短"},{"id":"glyph-seal-77ee","script":"seal","character":"矮","reading":"ǎi","description":"ǎi：(1)人的身材短～人。～矬。～个儿。～墩墩。\n(2)高度小～林。～墙。～屋。\n(3)等级地位低工资他比我～一级。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矮"},{"id":"glyph-seal-77f3","script":"seal","character":"石","reading":"shí；dàn","description":"shí：(1)构成地壳的矿物质硬块～破天惊（喻文章议论新奇惊人）。\n(2)指石刻金～。\n(3)指古代用来治病的针药～。药～之言（喻规劝别人的话）。\n(4)中国古代乐器八音之一。\n(5)姓。\ndàn：中国市制容量单位，十斗为一石。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-石"},{"id":"glyph-seal-77f6","script":"seal","character":"矶","reading":"jī","description":"水边突出的岩石或石滩\n矶jī 1.水冲击岩石。引申为激怒，触犯。 2.水边石滩或突出的岩石。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矶"},{"id":"glyph-seal-7800","script":"seal","character":"砀","reading":"dàng","description":"有花纹的石头\n砀,文石也。从石,?\n突然\n砀dàng 1.有花纹的石头。 2.荡漾;荡溢。 3.广大。 4.突;闯。 5.见\"砀极\"。 6.山名。在安徽省砀山县东南。 7.古地名。本战国楚邑，秦置县，隋改砀山。今安徽\n省砀山县。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砀"},{"id":"glyph-seal-780c","script":"seal","character":"砌","reading":"qì；qiè","description":"qì：(1)建筑时垒砖石，用泥灰粘合～墙。堆～（亦喻写文章时使用大量华丽而无用的词语）。\n(2)台阶雕栏玉～。\nqiè：〔～末〕中国元曲中称戏曲舞台上所用的简单布景和特制的器物。亦作切末”（末”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砌"},{"id":"glyph-seal-7814","script":"seal","character":"研","reading":"yán；yàn","description":"yán：(1)细磨（mó），碾～磨。～药。～墨。\n(2)深入地探求～究。钻～。～京练都（dū）（晋代左思作《三都赋》构思了十二年，后遂用研京练都”形容经年累月地构思文章）。\nyàn：古同砚”，砚台。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-研"},{"id":"glyph-seal-781a","script":"seal","character":"砚","reading":"yàn","description":"光滑的石头\n砚台\n制作砚\n⒈磨墨用的文具～台。\n⒉有同学关系的～兄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砚"},{"id":"glyph-seal-7823","script":"seal","character":"砣","reading":"tuó","description":"tuó：(1)碾子上的碌碡碾～。\n(2)秤锤秤～。\n(3)打磨玉器的砂轮，称砣子”。\n(4)用砣子打磨玉器～一个玉环。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砣"},{"id":"glyph-seal-7825","script":"seal","character":"砥","reading":"dǐ","description":"dǐ：细的磨刀石～石。～砺。\n〔～柱中流〕像砥柱山（在中国三门峡）那样屹立在黄河激流中，喻中坚人物或力量所起的支柱作用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砥"},{"id":"glyph-seal-7827","script":"seal","character":"砧","reading":"zhēn","description":"zhēn：(1)捶、砸或切东西的时候，垫在底下的器具～板。～子。\n(2)形状和作用像砧子的～骨（听骨之一）。～木。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砧"},{"id":"glyph-seal-782d","script":"seal","character":"砭","reading":"biān","description":"biān：(1)中国古代用以治病的石针～石。～针。\n(2)用石针扎皮肉治病，引申为刺或规劝～灸。针～（喻指出人的过错，劝人改正）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砭"},{"id":"glyph-seal-7834","script":"seal","character":"破","reading":"pò","description":"pò：(1)碎，不完整碗打～。～灭。～旧。～败。～落。～陋。～颜（转为笑容）。～绽（衣服裂开，指事情或说话的漏洞或矛盾）。牢不可～。\n(2)分裂～裂。～读（同一个字形因意义不同而有两个以上读音，把习惯上通常的读音之外的读音，称破读”）。～土。\n(3)使损坏～坏。～损。\n(4)超出～例。～格。\n(5)花费，耗费～费。～财。～产。\n(6)打败，打垮～阵。～门。攻～。\n(7)揭穿～案。～译。～获。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-破"},{"id":"glyph-seal-783a","script":"seal","character":"砺","reading":"lì","description":"引申为磨\n钻研;磨炼\n⒈粗的磨刀石。\n⒉磨～剑。～刀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砺"},{"id":"glyph-seal-783b","script":"seal","character":"砻","reading":"lóng","description":"用砻脱出稻谷的壳\n如砻坊;砻糠\n磨石\n脱出稻壳的农具\n通垄”。坟墓\n⒈去掉谷物壳的器具。\n⒉用砻去掉谷物的壳，也泛指磨～谷。～砺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砻"},{"id":"glyph-seal-783e","script":"seal","character":"砾","reading":"lì","description":"砾石\n砾石屋面\n砾岩\n砾luò 1.见\"卓砾\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砾"},{"id":"glyph-seal-7840","script":"seal","character":"础","reading":"chǔ","description":"事物的基底或根基","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-础"},{"id":"glyph-seal-7855","script":"seal","character":"硕","reading":"shuò","description":"引申为大\n通石”。比喻坚固\n学识渊博、德高望重的\n又患无硕师名人与游,","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硕"},{"id":"glyph-seal-7857","script":"seal","character":"硗","reading":"qiāo","description":"高低不平\n坚硬\n恶坏\n硗qiào 1.土地不平。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硗"},{"id":"glyph-seal-786e","script":"seal","character":"确","reading":"què","description":"坚定;坚决\n真实;符合事实\n通搉”。敲击\n乐亦不复\n⒋埆què\n⒈真实，实在～实。千真完～。～有其事。\n⒉肯定，坚定～认。～保不误。\n⒊土地瘠薄。\n⒋地不平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-确"},{"id":"glyph-seal-788c","script":"seal","character":"碌","reading":"lù；liù","description":"lù：(1)平凡（指人）庸～。～～（如忙忙～～”）。\n(2)繁忙劳～。忙～。\nliù：〔～碡〕农具，用来轧脱谷粒或轧平场院。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碌"},{"id":"glyph-seal-788d","script":"seal","character":"碍","reading":"ài","description":"遮蔽;掩盖\n妨害，阻挡～事。阻～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碍"},{"id":"glyph-seal-788e","script":"seal","character":"碎","reading":"suì","description":"suì：(1)完整的东西破坏成零片或零块～裂。粉～。粉身～骨。\n(2)零星，不完整～屑。琐～。～琼。支离破～。\n(3)说话唠叨嘴～。闲言～语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碎"},{"id":"glyph-seal-7891","script":"seal","character":"碑","reading":"bēi","description":"bēi：刻上文字纪念事业、功勋或作为标记的石头石～。丰～。墓～。口～。～文。～碣。～刻（刻在碑上的文字或图画）。～拓（tà）。～帖。～林。里程～（ａ．设于道路旁边用以记载里数的标志；ｂ．喻在历史发展进程中可以作为象征或标志的大事）。有口皆～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碑"},{"id":"glyph-seal-7893","script":"seal","character":"碓","reading":"duì","description":"duì：木石做成的捣米器具～房（舂米的作坊）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碓"},{"id":"glyph-seal-7897","script":"seal","character":"碗","reading":"wǎn","description":"wǎn：(1)盛（chéng）饮食的器皿，上面口大而圆饭～。茶～。盖～。～橱。\n(2)像碗的东西轴～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碗"},{"id":"glyph-seal-789b","script":"seal","character":"碛","reading":"qì","description":"浅水中的沙石;沙石浅滩\n沙漠\n⒈水中的沙堆。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碛"},{"id":"glyph-seal-78a3","script":"seal","character":"碣","reading":"jié；yà","description":"jié：圆顶的石碑残碑断～。墓～。\nyà：〔～磍（xiá）〕猛兽盛怒的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碣"},{"id":"glyph-seal-78a7","script":"seal","character":"碧","reading":"bì","description":"bì：(1)青绿色的玉石～玉。\n(2)青绿色～绿。金～辉煌。～空。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碧"},{"id":"glyph-seal-78b1","script":"seal","character":"碱","reading":"jiǎn","description":"jiǎn：(1)含在土里的一种物质，化学成分是碳酸钠，用做洗涤剂，亦用来中和发面中的酸味～土。～化。～荒。\n(2)化学上称能在水溶液中电离而生成氢氧离子（ＯＨ－）的化合物，如氢氧化钠等。溶液具有涩味，能使石蕊试纸变蓝，能跟酸中和而生成盐～金属。～式盐。～性岩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碱"},{"id":"glyph-seal-78ca","script":"seal","character":"磊","reading":"lěi","description":"lěi：石头多。\n〔～落（luò）〕心地光明坦白，如光明～～”，～～的胸怀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磊"},{"id":"glyph-seal-78d4","script":"seal","character":"磔","reading":"zhé","description":"zhé：(1)古代分裂牲体以祭神。\n(2)古代一种酷刑，把肢体分裂～刑。\n(3)汉字笔形之一，即捺（nà）”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磔"},{"id":"glyph-seal-78d5","script":"seal","character":"磕","reading":"kē","description":"kē：(1)碰在硬东西上头～破了。～～碰碰（喻人和人之间发生的小冲突）。～头碰脑。～头（亦作叩头”）。\n(2)把东西向较硬处碰使附着物掉下来～打。～烟袋锅儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磕"},{"id":"glyph-seal-78ec","script":"seal","character":"磬","reading":"qìng","description":"qìng：(1)古代打击兵器，形状像曲尺，用玉、石制成，可悬挂。\n(2)佛寺中使用的一种钵状物，用铜铁铸成，既可作念经时的打击乐器，亦可敲响集合寺众。\n(3)缢杀公族其有死罪，则～于甸人”。\n(4)古同罄”，空，尽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磬"},{"id":"glyph-seal-793a","script":"seal","character":"示","reading":"shì","description":"shì：(1)表明，把事物拿出来或指出来使别人知道～警。～范。～弱。～威。～众。～意。告～。指～。请～。\n(2)对来信的敬称赐～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-示"},{"id":"glyph-seal-793c","script":"seal","character":"礼","reading":"lǐ","description":"⒈尊敬或客气的态度、动作～貌。敬～。\n⒉适应社会的道德观念和习俗形成的仪式、仪节典～。婚～。\n⒊〈表〉庆贺或敬意的事物～物。～品。国庆献～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-礼"},{"id":"glyph-seal-793e","script":"seal","character":"社","reading":"shè","description":"shè：(1)古代指土地神和祭祀土地神的地方、日子以及祭礼春～。秋～。～日。～稷（社”是土神，稷”是谷神，古代君主都祭社稷，后用以借指国家）。\n(2)团体或机构报～。结～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-社"},{"id":"glyph-seal-7940","script":"seal","character":"祀","reading":"sì","description":"sì：(1)祭祭～。～天。～祖。\n(2)中国殷代指年十有三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祀"},{"id":"glyph-seal-7941","script":"seal","character":"祁","reading":"qí","description":"qí：(1)盛大～寒（严寒，极冷）。\n(2)姓。\n〔～～〕ａ．舒缓的样子；ｂ．众多的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祁"},{"id":"glyph-seal-7946","script":"seal","character":"祆","reading":"xiān","description":"xiān：〔～教〕拜火教，波斯人琐罗亚斯特所创立，崇拜火，今印度、伊朗还有信徒。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祆"},{"id":"glyph-seal-7947","script":"seal","character":"祇","reading":"ruǎn","description":"⒈古同磎”，次于玉的美石。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祇"},{"id":"glyph-seal-7948","script":"seal","character":"祈","reading":"qí","description":"qí：(1)向神求福～祷。～福。～年。\n(2)请求～请。～求。～望。敬～照准。\n(3)．姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祈"},{"id":"glyph-seal-7949","script":"seal","character":"祉","reading":"zhǐ","description":"zhǐ：福既多受～”。福～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祉"},{"id":"glyph-seal-7953","script":"seal","character":"祓","reading":"fú","description":"fú：古代用斋戒沐浴等方法除灾求福，亦泛指扫除～濯（洗濯）。～除（古代除凶去垢的仪式）。～禊（古代民俗，到水滨洗濯，洗去宿垢）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祓"},{"id":"glyph-seal-7956","script":"seal","character":"祖","reading":"zǔ","description":"zǔ：(1)父亲的上一辈～父。～考。～母。～妣。\n(2)称与祖父同辈的人外～父。外～母。\n(3)先代～宗。～业。～制。～祭。～国。\n(4)初，开始鼻～。\n(5)某种事业或派别的创始人～师。\n(6)出行时祭路神，引申为送行五月金陵西，～余白下亭”。～饯。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祖"},{"id":"glyph-seal-7957","script":"seal","character":"祗","reading":"zhī","description":"zhī：敬，恭敬～回。～仰。～奉。～承。～候。～应。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祗"},{"id":"glyph-seal-795a","script":"seal","character":"祚","reading":"zuò","description":"zuò：(1)福，赐福天～。福～。\n(2)皇位～命（赐予皇位）。\n(3)年初岁元～。吉日惟良”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祚"},{"id":"glyph-seal-795c","script":"seal","character":"祜","reading":"hù","description":"hù：福受天之～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祜"},{"id":"glyph-seal-795d","script":"seal","character":"祝","reading":"zhù","description":"zhù：(1)表示对人对事的美好愿望～福。～寿。～捷。～辞。馨香祷～。\n(2)古代指男巫。\n(3)在神庙里管香火的人～融。庙～。\n(4)断～发（fà）（断发，后指僧尼削发出家）。\n(5)姓。\n(6)古同注”，敷涂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祝"},{"id":"glyph-seal-795e","script":"seal","character":"神","reading":"shén","description":"shén：(1)迷信的人称天地万物的创造者和所崇拜的人死后的精灵～仙。～怪。～主。～社。～农。～甫。～权。鬼使～差。\n(2)不可思议的，特别希奇的～秘。～奇。～异。～话。～机妙算。\n(3)不平凡的，特别高超的～勇。～医。～通。～圣。～速。\n(4)心思，心力，注意力劳～。凝～。～魂颠倒。\n(5)表情～色。～采。～姿。～志。\n(6)精神～清气爽。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-神"},{"id":"glyph-seal-795f","script":"seal","character":"祟","reading":"suì","description":"suì：迷信说法指鬼神给人带来的灾祸，借指不正当的行动作～。鬼鬼～～。邪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祟"},{"id":"glyph-seal-7960","script":"seal","character":"祠","reading":"cí","description":"cí：(1)封建制度下供奉祖宗、鬼神或有功德的人的房屋～堂。～庙。宗～。\n(2)古代指春祭（品物少，多文词）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祠"},{"id":"glyph-seal-7962","script":"seal","character":"祢","reading":"mí","description":"奉祀死父的宗庙\n古代军旅之事,常载神主而行,随行神主称弥\n祢nǐ 1.亲庙;父庙。 2.父死，神主入庙后称祢。 3.随军的神主。 4.继承;崇奉。 5.古地名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祢"},{"id":"glyph-seal-7965","script":"seal","character":"祥","reading":"xiáng","description":"xiáng：(1)吉利～和。～瑞（吉祥的征兆）。不～。吉～。\n(2)吉凶的预兆～麟。～云。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祥"},{"id":"glyph-seal-7968","script":"seal","character":"票","reading":"piào；piāo","description":"piào：(1)纸币，通货钞～。～子。～额。\n(2)印的或写的凭证～据。～证。股～。车～。选～。\n(3)非职业演戏～戏。～友。\n(4)量词，相当于批”一～货物。\n(5)被匪绑架做抵押的人绑～儿。撕～儿。\npiāo：古同飘”，随风摆动飞扬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-票"},{"id":"glyph-seal-796d","script":"seal","character":"祭","reading":"jì；zhài","description":"jì：(1)对死者表示追悼、敬意的仪式～奠。～礼。～灵。～典。～扫。\n(2)供奉鬼神或祖先～祖。～天。～祀。～灶。\n(3)使用（法宝）～起一件法宝。\nzhài：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祭"},{"id":"glyph-seal-796f","script":"seal","character":"祯","reading":"zhēn","description":"祯zhēn吉祥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祯"},{"id":"glyph-seal-7977","script":"seal","character":"祷","reading":"dǎo","description":"祈祷,祈神求福\n①教徒或迷信的人向天、神求助～告。\n【祷告】宗教徒向天、神求保佑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祷"},{"id":"glyph-seal-7978","script":"seal","character":"祸","reading":"huò","description":"祸及枯骨。\n⒈灾害，苦难，跟\"福\"相对闯～了。出了车～。遭～殃。～兮福所倚，福兮～所伏。\n⒉损害，桅～害。～人之心。～国殃民。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祸"},{"id":"glyph-seal-797a","script":"seal","character":"祺","reading":"qí","description":"qí：吉祥，安祥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祺"},{"id":"glyph-seal-7980","script":"seal","character":"禀","reading":"bǐng","description":"bǐng：(1)承受，生成的～性。～赋。\n(2)指下对上报告～报。～复。回～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禀"},{"id":"glyph-seal-7981","script":"seal","character":"禁","reading":"jìn；jīn","description":"jīn：(1)受得住，耐久～受。～得住。～不起。弱不～风。\n(2)忍耐，制止不～笑起来。\njìn：(1)不许，制止～止。～绝。～书。～令。～赌。～欲。～锢。情不自～。\n(2)法律或习惯上制止的事犯～。违～品。\n(3)拘押囚～。监～。～闭。\n(4)古代称帝王的地方宫～。～苑。～卫。～军（古代指保卫京城或宫廷的军队）。\n(5)不能随便通行的地方～地。～区。\n(6)避忌～忌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禁"},{"id":"glyph-seal-7984","script":"seal","character":"禄","reading":"lù","description":"lù：(1)古代官吏的俸给～米。～位（借指官职）。～蠹（指追求官禄的人）。～食。俸～。无功受～。\n(2)福儿已薄～相，幸复得此妇”。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禄"},{"id":"glyph-seal-7985","script":"seal","character":"禅","reading":"chán","description":"表示与佛教有关的事物\n指禅房\n注除地于梁甫之阴,为墠\n①佛教用语。指静坐坐～。\n【禅定】〈宗〉佛教修行方法之一。安定而排除杂念的意思。禅定时，只能静坐，不能躺卧。认为如此能达到'明净'、'无我'的状态。俗称'坐禅'、'打坐'。\n【禅学】〈宗〉魏晋时期的佛学派别。偏重宗教修持，主要流行于北方◇也泛指佛学特别是禅宗一派。\n【禅宗】佛教的一派。以静坐默念为修行方法。据说南朝时菩提达摩来华传授禅法，经慧可、弘忍、惠能等的继承和发展，得以广泛流行。它以通俗易懂的修行方法取代其他宗\n派的繁琐理论，流行很广，唐宋时极盛。\n⒈梵文\"禅那\"的简称。意译为\"静思\"。佛教的一种修行法坐～。参～。又指有关佛教的～寺。～杖。\n⒈〈古〉帝王祭地的一种迷信礼仪。\n⒉禅让，指帝王让位给别人尧～位于舜。舜～位于禹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禅"},{"id":"glyph-seal-798f","script":"seal","character":"福","reading":"fú","description":"fú：(1)一切顺利，幸运，与祸”相对～气。享～。造～。祝～。～利。～音。～相。作威作～（原指统治者专行赏罚，独揽威权◇形容滥用权势，横行霸道）。\n(2)旧时妇女行礼的姿势万～。\n(3)祭神的酒肉～食。～酒。～物。\n(4)保祐小信未孚，神弗～也”。～荫。～佑。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-福"},{"id":"glyph-seal-79a7","script":"seal","character":"禧","reading":"xǐ","description":"xǐ：(1)（旧读xī）福，吉祥年～。福～。\n(2)喜庆～贺。新～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禧"},{"id":"glyph-seal-79b3","script":"seal","character":"禳","reading":"ráng","description":"ráng：祈祷消除灾殃～解。～灾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禳"},{"id":"glyph-seal-79b9","script":"seal","character":"禹","reading":"yǔ","description":"yǔ：(1)传说中国夏代的第一个君主，他曾经治过洪水～域（指中国的疆域）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禹"},{"id":"glyph-seal-79ba","script":"seal","character":"禺","reading":"yú；yù；ǒu","description":"yú：古代区域十～（十华里的地方）。\n〔～谷〕古代传说中日落处。亦作虞谷”、隅谷”。\n〔～强〕古代传说中的神。\n〔～～〕古代传说中的一种鱼。\nyù：古代传说中的一种猴。\nǒu：古同偶”，偶像。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禺"},{"id":"glyph-seal-79bb","script":"seal","character":"离","reading":"lí","description":"长离,传说中的凤鸟,比喻有才华的人\n八卦之一,象征火\n⒈分开，分别～开。～别。～婚。～职。分～。\n⒉违背背～。\n⒊相距，隔开距～。隔～。我家～学校有一里路。\n⒋缺少生活～不了粮食。\n⒌八卦之一，代表火。\n离chī 1.古代传说中的一种龙。 2.猛兽。\n离gǔ 1.山名用字。\n离lì 1.丧失。 2.去掉;弃。\n离lǐ 1.见\"离跂\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-离"},{"id":"glyph-seal-79bd","script":"seal","character":"禽","reading":"qín","description":"qín：(1)鸟、兽的总称五～戏。\n(2)特指鸟类家～。飞～走兽。\n(3)古通擒”不～二毛。”\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禽"},{"id":"glyph-seal-79be","script":"seal","character":"禾","reading":"hé","description":"hé：(1)谷类植物的统称～苗。～本科（单子叶植物的一科）。\n(2)古代指粟（谷子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禾"},{"id":"glyph-seal-79c0","script":"seal","character":"秀","reading":"xiù","description":"xiù：(1)植物吐穗开花，多指庄稼～穗。～而不实（喻人很聪明，却未做出实际成绩）。苗而不～（喻人早死或虚有其表）。\n(2)特别优异的，亦指特别优异的人～异。～才。优～◇起之～。\n(3)美丽而不俗气～丽。～劲。～俊。～拔（秀丽而挺拔）。清～。～外慧中（外貌俊美，内心聪明）。\n(4)中国元明两代称贵族、官僚、富室子弟（称平民子弟为郎”）不郎不～（喻不成材或没出息）。\n(5)茂盛佳木～而繁荫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秀"},{"id":"glyph-seal-79c1","script":"seal","character":"私","reading":"sī","description":"sī：(1)个人的，自己的，与公”相对～人。～有。～见。～仇。～情。～营。～欲。\n(2)不公开的，秘密而又不合法的～自。～刑。～货。走～。～生子。\n(3)暗地里～议。～奔。隐～。窃窃～语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-私"},{"id":"glyph-seal-79c3","script":"seal","character":"秃","reading":"tū","description":"tū：(1)人无头发，山无树木，树木无枝叶～子。～头。～顶。\n(2)鸟羽毛脱落，物体失去尖端～鹫。～笔。～针。\n(3)表示不圆满、不周全文章的开头写得有点～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秃"},{"id":"glyph-seal-79c6","script":"seal","character":"秆","reading":"gǎn","description":"gǎn：稻麦等植物的茎麦～儿。麻～儿。高粱～儿。烟～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秆"},{"id":"glyph-seal-79c9","script":"seal","character":"秉","reading":"bǐng","description":"bǐng：(1)拿着，持～烛。\n(2)掌握、主持～正。～公。\n(3)古代容量单位，一秉合六十斛。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秉"},{"id":"glyph-seal-79cb","script":"seal","character":"秋","reading":"qiū","description":"一年四季中的秋季，常与收获相联系。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-79cd","script":"seal","character":"种","reading":"zhǒng；zhòng；chóng","description":"zhǒng：物种、种类、种子。zhòng：播种、栽种。chóng：姓氏。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-79d1","script":"seal","character":"科","reading":"kē","description":"kē：(1)动植物的分类单位狮子属于猫～。槐树是豆～。\n(2)机关内部组织的划分～室。财务～。\n(3)学术或专业的类别～目。学～。文～。外～。\n(4)古代分科考选文武官吏后备人员的制度～举。～甲。～第。登～。\n(5)判定（刑罚）～处（chǔ）。～罚。\n(6)古典戏剧本中指示角色表演动作时的用语笑～。～白。\n(7)古同棵”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-科"},{"id":"glyph-seal-79d2","script":"seal","character":"秒","reading":"miǎo","description":"miǎo：(1)谷物种子壳上的芒，引申为细微，微小～忽（喻细微）。\n(2)时间的计算单位，一分钟的六十分之一～表。～针。\n(3)弧和角的计算单位，一分的六十分之一。\n(4)经纬度的计算单位，一分的六十分之一。\n(5)古代长度单位，一寸的万分之一。\n(6)古代容量单位，十撮为一秒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秒"},{"id":"glyph-seal-79d5","script":"seal","character":"秕","reading":"bǐ","description":"bǐ：(1)子实不饱满～子（不饱满的子实）。～糠（秕子和糠，喻没有价值的东西）。\n(2)坏，不良～政（不良的政治措施）。\n(3)古同纰”，纰谬。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秕"},{"id":"glyph-seal-79d8","script":"seal","character":"秘","reading":"mì；bì","description":"mì：(1)不公开的，不让大家知道的～密。～藏（cáng）。～方。～诀。～计。～史。神～。奥～。\n(2)保守秘密～而不宣。\n(3)珍贵罕见～本。～籍。～宝。～府。\n(4)姓。\nbì：〔～鲁〕国名，在南美洲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秘"},{"id":"glyph-seal-79df","script":"seal","character":"租","reading":"zū","description":"zū：(1)出代价暂用别人的东西～房。～用。～借地。\n(2)收取一定的代价，把房屋、土地、器物等借给别人使用～佃。～价。～让。～赁（ａ．出租；ｂ．租用）。\n(3)出租所收取的钱或实物房～。地～。\n(4)田赋～税。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-租"},{"id":"glyph-seal-79e4","script":"seal","character":"秤","reading":"chèng","description":"chèng：衡量轻重的器具市～。磅～。～砣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秤"},{"id":"glyph-seal-79e6","script":"seal","character":"秦","reading":"qín","description":"qín：(1)中国周代诸侯国名，在今陕西省和甘肃省一带朝（zhāo）～暮楚。～晋之好。～楼楚馆（旧时指妓院）。\n(2)中国朝代名～代。～镜高悬（喻法官判案的公正严明。亦称明镜高悬”）。\n(3)中国陕西省的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秦"},{"id":"glyph-seal-79e7","script":"seal","character":"秧","reading":"yāng","description":"yāng：(1)植物的幼苗～苗。树～儿。～田。育～。插～（特指稻苗）。\n(2)某些植物的茎瓜～。拉～。\n(3)某些初生的小动物鱼～子。\n(4)栽植；畜养～几棵树。他～了一池鱼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秧"},{"id":"glyph-seal-79e9","script":"seal","character":"秩","reading":"zhì","description":"zhì：(1)有条理，不混乱的情况～序。\n(2)古代官吏的俸禄官人益～，庶人益禄”。\n(3)古代官职级别委之常～。贬～三等。\n(4)十年七～寿辰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秩"},{"id":"glyph-seal-79eb","script":"seal","character":"秫","reading":"shú","description":"shú：黏高粱，可以做烧酒，有的地区泛指高粱～秸。～米（高粱米）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秫"},{"id":"glyph-seal-79ed","script":"seal","character":"秭","reading":"zǐ","description":"zǐ：古代数目名，一万亿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秭"},{"id":"glyph-seal-79ef","script":"seal","character":"积","reading":"jī","description":"累积;堆叠\n⒈堆积谷物农收～场。〈引〉堆积，聚集～肥。～少致巨。日～月累。～土而为山，～水而为海。\n⒊停滞～食。\n⒋算数乘法的得数乘～。\n①正面的，进步的～极因素。～极分子。\n②进取的，努力的～极争取。～极工作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-积"},{"id":"glyph-seal-79f0","script":"seal","character":"称","reading":"chēng；chen","description":"符合,相当\n测定重量\n称 chèn合适；相当～心如意。又见chēng。\n【称体裁衣】按照身体的长短大小裁衣服。比喻做事要恰到好处。\n【称职】才能与职位相称；思想、能力等能胜任所担任的职务。\n①叫；叫做人们～他为老英雄。\n②名称昵～、蔑～。\n③说连声～好、点头～是。\n④赞扬～许。\n⑤测重量～2斤糖。\n⑥举～觞。又见chèn。\n【称道】称赞；夸奖值得～。\n【称孤道寡】以帝王、首脑自居。'孤'、'寡人'均为古代封建帝王的自称。现多讽刺自大的人。\n【称量瓶】精确称量分析试样用的小型玻璃仪器。一般为圆柱形，带有磨口密合的瓶盖。\n【称叹】赞叹～不已。\n【称谓】人们由于血缘和其他方面的相互关系以及由于身分、职业等等而得来的名称。如父亲、同志、先生、姑姑等。\n【称羡】称赞羡慕。\n【称雄】凭借武力或其他势力统治一方割据～。\n【称许】赞许。\n【称誉】表扬赞美。\n⒈衡量轻重～三斤肉。\n⒉名号名～。省～。别～。\n⒊叫，叫做～谓。～作。～兄道弟。\n⒋说，声言～谢。～好。～病。声～。\n⒌颂扬，赞许～颂。～许。～赞。\n⒍举，推举～兵。～贤举能。\n⒈适合，相当，相等～心。～职。相～。对～。德必～位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-称"},{"id":"glyph-seal-79f8","script":"seal","character":"秸","reading":"jiē","description":"jiē：农作物收割以后的茎麦～。豆～。秫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秸"},{"id":"glyph-seal-79fb","script":"seal","character":"移","reading":"yí","description":"yí：(1)挪动～交。～植。～刻（过一段时间）。～晷（日影移动，犹言经过了一段时间）。～民。迁～。转～。～樽就教（端着酒去别人跟前以便求教，泛指主动前去向人请教）。\n(2)改变，变动～居。～易。～情（变易人的情志）。～动。潜～默化。\n(3)旧时公文的一种，行文不相统属的官署间～文。檄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-移"},{"id":"glyph-seal-7a00","script":"seal","character":"稀","reading":"xī","description":"xī：(1)事物中间距离远、空隙大，与密”相对，～疏。～落（luò）。～客。依～。\n(2)浓度小，含水分多的，与稠”相对～薄。～料。～释。\n(3)少～少。～罕。～奇。古～之年。\n(4)用在烂”、松”等形容词前面，表明程度深～烂。～碎。～松。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稀"},{"id":"glyph-seal-7a02","script":"seal","character":"稂","reading":"láng","description":"láng：害禾苗的杂草～莠。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稂"},{"id":"glyph-seal-7a03","script":"seal","character":"稃","reading":"fū","description":"fū：小麦等植物的花外面包着的硬壳内～。外～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稃"},{"id":"glyph-seal-7a0b","script":"seal","character":"程","reading":"chéng","description":"chéng：(1)规矩，法式～式。～序。章～。规～。\n(2)进展，限度～度。进～。日～。过～。\n(3)道路的段落路～。行（xíng）～。里～。启～。前～。\n(4)衡量，考核计日～功。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-程"},{"id":"glyph-seal-7a0d","script":"seal","character":"稍","reading":"shāo；shào","description":"shāo：本义为禾末，引申为略微～～。～微。～许。～纵即逝。\nshào：〔～息〕军事或体操的口令。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稍"},{"id":"glyph-seal-7a0e","script":"seal","character":"税","reading":"shuì","description":"shuì：(1)国家向企业或集体、个人征收的货币或实物～收。～额。～款。～率。～法。～制。～务。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-税"},{"id":"glyph-seal-7a14","script":"seal","character":"稔","reading":"rěn","description":"rěn：(1)庄稼成熟丰～。～年（丰收之年）。岁比登～”。\n(2)年，古代谷一熟为年凡五～。\n(3)熟悉，习知～知。～熟。素～。相～。\n(4)事物酝酿成熟恶积衅～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稔"},{"id":"glyph-seal-7a17","script":"seal","character":"稗","reading":"bài","description":"bài：(1)一年生草本植物，长在稻田里或低湿的地方，形状像稻，是稻田的害草。果实可酿酒、做饲料。\n(2)喻微小的，琐碎的～官（古代的一种小官，专给帝王述说街谈巷议、市井传闻◇泛称记载轶闻琐事的文字为～～野史”）。～史（记载轶闻琐事的书）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稗"},{"id":"glyph-seal-7a1a","script":"seal","character":"稚","reading":"zhì","description":"zhì：幼小幼～。～气。～子。～嫩。～弱。～拙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稚"},{"id":"glyph-seal-7a1e","script":"seal","character":"稞","reading":"kē","description":"kē：〔青～〕麦子的一种，粒大，皮薄，主要产在中国西藏、青海等地，是藏族人民的主要食品糌粑的原料，又可酿酒。亦称稞麦”、元麦”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稞"},{"id":"glyph-seal-7a20","script":"seal","character":"稠","reading":"chóu","description":"chóu：(1)密，与稀”相对～密。～人广众。\n(2)浓～粥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稠"},{"id":"glyph-seal-7a23","script":"seal","character":"稣","reading":"sū","description":"同苏”\n转意为死而复生,苏醒,复活。今作苏”\n稣sū同\"苏","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稣"},{"id":"glyph-seal-7a33","script":"seal","character":"稳","reading":"wěn","description":"妥帖;稳妥\n⒈安定，固定，不动摇～定。～当。～如泰山。\n⒉妥贴～妥。\n⒊沉着，不轻浮～重。～健。\n⒋准确，有把握～操胜劵。～扎～打。\n⒌诱使他人暂缓行动你先～住他。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稳"},{"id":"glyph-seal-7a37","script":"seal","character":"稷","reading":"jì","description":"jì：(1)古代一种粮食作物，指粟或黍属。\n(2)古代以稷为百谷之长，因此帝王奉祀为谷神社～（指国家）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稷"},{"id":"glyph-seal-7a3b","script":"seal","character":"稻","reading":"dào","description":"dào：一年生草本植物，子实称稻谷”，去壳后称大米”。有水稻、旱稻之分。通常指水稻～子。～草。～米（亦称大米”）。～糠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稻"},{"id":"glyph-seal-7a3c","script":"seal","character":"稼","reading":"jià","description":"jià：(1)种植谷物，亦泛指农业劳动～穑。耕～。\n(2)谷物庄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稼"},{"id":"glyph-seal-7a3d","script":"seal","character":"稽","reading":"jī；qǐ","description":"jī：(1)停留～留。～滞。\n(2)考核～核。～查。～考。无～之谈。\n(3)计较反唇相～。\n(4)至。\n(5)姓。\nqǐ：〔～首〕古代的一种礼节，跪下，拱手至地，头也至地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稽"},{"id":"glyph-seal-7a3f","script":"seal","character":"稿","reading":"gǎo","description":"gǎo：(1)谷类植物的茎秆～秆。～荐（稻草编的垫子）。\n(2)文字、图画的草底，又喻事先考虑的计划文～。～本。～件。讲～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稿"},{"id":"glyph-seal-7a46","script":"seal","character":"穆","reading":"mù","description":"mù：(1)温和；～清（ａ．清平；ｂ．指上天）。～如清风。\n(2)恭敬严肃肃～。静～。\n(3)古同默”，沉默。\n(4)古代宗庙次序，父居右为昭”，子居左为穆”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穆"},{"id":"glyph-seal-7a51","script":"seal","character":"穑","reading":"sè","description":"通啬”。节俭;爱惜\n⒈收割庄稼不稼不～。\n⒉〈古〉通\"啬\"。节省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穑"},{"id":"glyph-seal-7a57","script":"seal","character":"穗","reading":"suì","description":"suì：(1)禾本植物聚生在茎的顶端的花和果实麦～。稻～。谷～。～轴。～状花序。\n(2)用丝线、布条或纸条等扎成的、挂起来往下垂的装饰品灯笼～儿。\n(3)中国广东省广州市的别称。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穗"},{"id":"glyph-seal-7a70","script":"seal","character":"穰","reading":"ráng","description":"ráng：(1)稻、麦等的秆～草。～子。\n(2)庄稼丰熟～～（丰盛的样子）。\n(3)同瓤”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穰"},{"id":"glyph-seal-7a74","script":"seal","character":"穴","reading":"xué","description":"xué：(1)洞，窟窿孔～。石～。～居。～隙。龙潭虎～。\n(2)人体可以进行针灸的部位，多为神经末梢密集或较粗的神经干经过的地方～位。\n(3)旧艺人称在市场或广场上表演时所占的一块地方掌～的（指地主或班主）。走～。～头。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穴"},{"id":"glyph-seal-7a76","script":"seal","character":"究","reading":"jiū","description":"jiū：(1)推求，追查研～。推～。讲～。追～。深～。有案必～。\n(2)极，到底～竟（ａ．到底，如～～想干什么？”ｂ．结果，如大家都想知道个～～”）。终～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-究"},{"id":"glyph-seal-7a77","script":"seal","character":"穷","reading":"qióng","description":"⒈不得志，不显贵，跟\"达\"相对～不失义。\n⒉阻塞，不通，走投无路，跟\"通\"相对日暮途～。追～寇。\n⒊生活、处境困难～苦。～困。～则思变。\n⒋尽，完结理屈词～。无～无尽。\n⒌极端，彻底推究～凶极恶。～根究底。\n穷gōng 1.身体。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穷"},{"id":"glyph-seal-7a79","script":"seal","character":"穹","reading":"qióng","description":"qióng：(1)隆起～隆。\n(2)天空～苍（天空。亦称苍穹”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穹"},{"id":"glyph-seal-7a7a","script":"seal","character":"空","reading":"kōng；kòng；kǒng","description":"kōng：(1)不包含什么，没有内容～洞（ａ．没有内容的；ｂ．物体内部的窟窿）。～泛。～话。～旷。～乏。～～如也。～前绝后。凭～（无根据）。真～（没有任何东西）。\n(2)没有结果的，白白地～跑了一趟。～口无凭。\n(3)离开地面的，在地上面的地方～军。～气。～投。～运。\nkòng：(1)使空，腾出来～一个格。～出一间房来。\n(2)闲着，没被利用的～白。～地。～额。～房。～缺。\n(3)亏欠亏～。\nkǒng：古同孔”，洞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-空"},{"id":"glyph-seal-7a7f","script":"seal","character":"穿","reading":"chuān","description":"chuān：(1)破，透～透。揭～。～窬（钻洞和爬墙，指盗贼）。～凿。\n(2)通过，连通～过。～行（xíng）。\n(3)着（zhuó）衣服鞋袜～衣。～鞋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穿"},{"id":"glyph-seal-7a81","script":"seal","character":"突","reading":"tū","description":"tū：(1)忽然～然。～现。～发。～变。～如其来。异军～起。～兀。\n(2)超出，冲破，猛冲～破。～围。～出。\n(3)烟囱曲～徙薪。灶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-突"},{"id":"glyph-seal-7a83","script":"seal","character":"窃","reading":"qiè","description":"篡夺。指非其有而取之;不当受而受之\n⒈偷，用不合法、不正当的手段取得偷～。盗～犯。～据。～国大盗。\n⒉暗中，偷偷地～听。～取。～探。\n⒊私自，私下，旧时谦称自己～谓。～以为不妥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窃"},{"id":"glyph-seal-7a88","script":"seal","character":"窈","reading":"yǎo","description":"yǎo：深远，幽静～冥（亦作杳冥”）。～～。～霭。\n〔～窕〕ａ．形容女子文静而美好；ｂ．（宫室、山水）深远曲折。\n〔～娜（nuó）窈窕婀娜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窈"},{"id":"glyph-seal-7a8d","script":"seal","character":"窍","reading":"qiào","description":"指耳鼻目口等器官之孔\n比喻事情的关键或要害\n⒉〈喻〉事情的关键或巧妙的方法～门。诀～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窍"},{"id":"glyph-seal-7a91","script":"seal","character":"窑","reading":"yáo","description":"yáo：(1)烧砖、瓦、陶瓷器的构筑物砖～。瓷～。\n(2)为采煤而凿的洞煤～。\n(3)在坡上特为住人挖的洞～洞。～葬。\n(4)旧时称妓院～子。～姐（妓女）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窑"},{"id":"glyph-seal-7a92","script":"seal","character":"窒","reading":"zhì","description":"zhì：阻塞不通～息。～塞。～闷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窒"},{"id":"glyph-seal-7a95","script":"seal","character":"窕","reading":"tiǎo；yáo","description":"tiǎo：(1)细小者不～。”\n(2)有空隙充盈大宇而不～”。\n(3)美好秦晋之间，凡美色，或谓之好，或谓之～”。\nyáo：妖艳，轻挑～冶。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窕"},{"id":"glyph-seal-7a96","script":"seal","character":"窖","reading":"jiào","description":"jiào：(1)收藏东西的地洞或坑～穴。～子。地～。\n(2)把东西藏在地窖里～藏。～白菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窖"},{"id":"glyph-seal-7a97","script":"seal","character":"窗","reading":"chuāng","description":"chuāng：房屋通风透气的装置～子。～户。～口。～友（即同学）。～花。～台。～纱。～帘。～幔。～明几净。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窗"},{"id":"glyph-seal-7a98","script":"seal","character":"窘","reading":"jiǒng","description":"jiǒng：(1)穷困～厄。～乏。～苦。～困。～迫。～促。～急。\n(2)难住，使为难～况。～态。～相。～境。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窘"},{"id":"glyph-seal-7a9c","script":"seal","character":"窜","reading":"cuàn","description":"奔逃\n放逐\n删改\n羼杂;混入\n骚扰\n②放逐；驱逐；贬官。\n【窜红】走红。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窜"},{"id":"glyph-seal-7aa0","script":"seal","character":"窠","reading":"kē","description":"kē：(1)昆虫、鸟兽的巢穴～巢。狗～。\n(2)借指人安居或聚会的处所抛却山中诗酒～”。\n(3)古同颗”。\n(4)古同棵”。\n〔～臼〕指文章所依据的老套子，陈旧的格调。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窠"},{"id":"glyph-seal-7aa3","script":"seal","character":"窣","reading":"sū","description":"见“窸窣”，形容细小的摩擦声，如衣物或落叶的声响。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7aa5","script":"seal","character":"窥","reading":"kuī","description":"暗中察看。亦泛指观看\n观察,侦探\n伺机图\n窥kuǐ 1.半步。言一举足即到。 2.引申为到。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窥"},{"id":"glyph-seal-7aa6","script":"seal","character":"窦","reading":"dòu","description":"门旁小户\n泛指简陋门户\n古代椭圆形地窖\n①孔洞。\n②人体某些器官内部凹入的部分鼻～。\n③姓。\n【窦娥冤】元代剧作家关汉卿的代表作。写窦娥冤屈而死的故事，反映了当时黑暗的社会现实，塑造了一个富有反抗精神的妇女形象。\n车师一带北匈奴势力◇官至光禄勋、卫尉。\n世充，与李世民在河南荥阳决战，兵败被俘，被杀于长安。\n窦dú 1.大川。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窦"},{"id":"glyph-seal-7aa8","script":"seal","character":"窨","reading":"xūn；yìn","description":"yìn：(1)地下室地～子。～井（为便于检查、疏通地下管线而设置的井状构筑物）。\n(2)藏在地窨里。～藏。\nxūn：同熏”，用于窨茶叶”（把茉莉花等放在茶叶中，使茶叶染上花的香味）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窨"},{"id":"glyph-seal-7ab3","script":"seal","character":"窳","reading":"yǔ","description":"yǔ：(1)（事物）恶劣，粗劣～劣。～败（腐败；败坏）。～陋（粗劣，质量很差）。良～（优劣）。\n(2)懒～惰。\n(3)瘦弱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窳"},{"id":"glyph-seal-7acb","script":"seal","character":"立","reading":"lì","description":"lì：(1)站，引申为竖起来～正。～柜。～足（ａ．站得往脚；ｂ．处于某种立场）。～场。屹～。顶天～地。\n(2)做出，定出建～。设～。树～。～意。～此存照。\n(3)存在，生存自～。独～。势不两～。\n(4)马上，即刻～时。～刻。～等。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-立"},{"id":"glyph-seal-7ad6","script":"seal","character":"竖","reading":"shù","description":"纵。与横”相反\n短小\n童仆\n⒈立，直立～立。～栅列营。将竹竿～起来。\n⒉上下或前后的方向，跟\"横\"相对～排。～着砌道墙。\n⒊直『字笔形之一，从上往下写\"干\"字是二横一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竖"},{"id":"glyph-seal-7ade","script":"seal","character":"竞","reading":"jìng","description":"争辩\n⒈争逐，比赛，互相争胜～走。～赛。～争。\n⒉强劲南风不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竞"},{"id":"glyph-seal-7adf","script":"seal","character":"竟","reading":"jìng","description":"jìng：(1)终了，完毕继承先烈未～的事业。\n(2)到底，终于毕～。有志者事～成。\n(3)整，从头到尾～日。～夜。\n(4)居然，表示出乎意料～然。～至（竟然至于）。～自（竟然）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竟"},{"id":"glyph-seal-7ae0","script":"seal","character":"章","reading":"zhāng","description":"zhāng：(1)歌曲诗文的段落～节。～句。乐～。～回体。顺理成～。断～取义。\n(2)条目，规程～程。～法。简～。党～。约法三～。\n(3)修理杂乱无～。\n(4)花纹，文采黑质而白～。\n(5)戳记图～。盖～。\n(6)佩带的身上的标志袖～。领～。徽～。像～。\n(7)奏本奏～。本～。\n(8)古同彰”，彰明。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-章"},{"id":"glyph-seal-7ae3","script":"seal","character":"竣","reading":"jùn","description":"jùn：事情完毕～事。～工。完～。大功告～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竣"},{"id":"glyph-seal-7ae5","script":"seal","character":"童","reading":"tóng","description":"tóng：(1)小孩子儿～。～工。～谣。～话。～心。～趣。～真。\n(2)旧时未成年的仆人书～儿。\n(3)没有结婚的～男。～女。～贞。\n(4)未长成的～牛（没长角的小牛）。\n(5)秃～山。头～（喻人秃顶，如～～齿豁”）。\n(6)古同瞳”，瞳孔。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-童"},{"id":"glyph-seal-7ae6","script":"seal","character":"竦","reading":"sǒng","description":"sǒng：(1)伸长脖子，提起脚跟站着～立。\n(2)恭敬，肃敬～然异之”。\n(3)同悚”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竦"},{"id":"glyph-seal-7aed","script":"seal","character":"竭","reading":"jié","description":"jié：尽，用尽～诚。～尽。～力。～泽而渔。枯～。衰～。声嘶力～。用之不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竭"},{"id":"glyph-seal-7aef","script":"seal","character":"端","reading":"duān","description":"duān：(1)正，不歪斜～正（ａ．事物不歪斜；ｂ．正派，正确；ｃ．使端正）。～丽。～然。～庄。～秀。～静。～坐。\n(2)正派，正直～方。～直。～重（zhòng）。品行不～。\n(3)事物的一头～的（dì）（ａ．事情的经过，底细；ｂ．的确，果然；ｃ．究竟。均亦称端底”）。～倪。～详。事～。争～。\n(4)用手很平正地拿～盆。～碗。～茶。把问题～出来说清楚。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-端"},{"id":"glyph-seal-7af9","script":"seal","character":"竹","reading":"zhú","description":"茎有节的植物，常见于诗词与绘画。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-7afa","script":"seal","character":"竺","reading":"zhú；dǔ","description":"zhú：姓。\n〔天～〕印度的古称。\ndǔ：古同笃”，厚。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竺"},{"id":"glyph-seal-7afd","script":"seal","character":"竽","reading":"yú","description":"yú：古代吹奏乐器，像笙，有三十六簧滥～充数。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竽"},{"id":"glyph-seal-7aff","script":"seal","character":"竿","reading":"gān","description":"gān：(1)竹子的主干竹～。立～见影。揭～而起。\n(2)特指钓鱼竿”垂～。投～。～钓。\n(3)古代指竹简～牍（书信）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竿"},{"id":"glyph-seal-7b03","script":"seal","character":"笃","reading":"dǔ","description":"忠实,不虚伪\n①忠实～信。\n【笃厚】诚实厚道。\n【笃实】\n①忠诚老实。\n②扎实学问～。\n【笃信】忠实地信仰。\n【笃学】专心好学。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笃"},{"id":"glyph-seal-7b04","script":"seal","character":"笄","reading":"jī","description":"jī：(1)古代的一种簪子，用来插住挽起的头发，或插住帽子发～。弁～。\n(2)古代特指女子十五岁可以盘发插笄的年龄，即成年及～。～年。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笄"},{"id":"glyph-seal-7b0b","script":"seal","character":"笋","reading":"sǔn","description":"sǔn：(1)竹子初从土里长出的嫩茎、芽，又称竹笋”，可以做菜吃。可食用者主要有毛竹笋”、慈竹笋”、麻竹笋”等。\n(2)竹子的青皮～席（用竹青编成的席子）。\n(3)古同榫”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笋"},{"id":"glyph-seal-7b0f","script":"seal","character":"笏","reading":"hù","description":"hù：古代大臣上朝拿着的手板，用玉、象牙或竹片制成，上面可以记事朝（cháo）～。京兆尹郑叔则，怫然曳～却立”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笏"},{"id":"glyph-seal-7b11","script":"seal","character":"笑","reading":"xiào","description":"xiào：(1)露出愉快的表情，发出欢喜的声音～容。～颜。～眯眯。谈～风生。\n(2)讥嘲～柄。～话。～谈。贻～大方。嘲～。见～。耻～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笑"},{"id":"glyph-seal-7b14","script":"seal","character":"笔","reading":"bǐ","description":"指字画诗文等以笔书写绘制而成的作\n①写字画图的用具钢～、蜡～、粉～。\n③用笔写出代～。\n④笔画'二'字有两～。\n⑤量词一～帐、一～好字。\n【笔触】书画、文学作品等的笔法，格调锋利的～。\n【笔调】文章风格～清新。\n【笔端】写作、写字、绘画时的运笔以及所表现的意境奇光异景尽收～。\n【笔法】写字、画画、作文的技巧或特色这篇小说的～很新颖。\n【笔锋】\n①笔尖。\n②书画的笔势；文章的气势。\n【笔供】用笔写出来的供词。与'口供'相对。\n【笔画笔顺检字法】汉字字典查阅检索方法之一。要求根据笔画的多少和笔顺的先后来查检。\n【笔记文】文体的一种。以随笔记录为主，多由分条的短篇汇集而成。\n【笔力】写字、画画或做文章所表现出的功力～刚劲。\n【笔路】\n①笔法。\n②写作的思路这篇文章～奇特。\n【笔势】\n①写字、画画用笔的风格。\n②文章的气势。\n【笔削】古时在竹简、木简上写字，要删改得用刀刮去，称'削'◇来用做请人修改文章的敬辞。笔记录。削删改。\n【笔意】书画或诗文中所表现出的作者的意境。写字、绘画时运笔的精心构思以及所表现的风格、功力。也指诗文的意境。\n【笔札】札是古时写字用的小木片，后来用笔札指纸笔，又转指写的文章。\n【笔战】用文章来进行辩论，打官司，与'舌战'相对。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笔"},{"id":"glyph-seal-7b19","script":"seal","character":"笙","reading":"shēng","description":"shēng：管乐器名，一般用十三根长短不同的竹管制成，吹奏～歌。芦～。～管乐（yuè）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笙"},{"id":"glyph-seal-7b1b","script":"seal","character":"笛","reading":"dí","description":"dí：(1)管乐器名，通常是竹制的，有八孔，横着吹奏～子。长～。短～。～膜。\n(2)响声尖锐的发音器汽～。警～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笛"},{"id":"glyph-seal-7b1e","script":"seal","character":"笞","reading":"chī","description":"chī：(1)用鞭杖或竹板打鞭～。\n(2)古代用竹板或荆条打人脊背或臀腿的刑罚～刑。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笞"},{"id":"glyph-seal-7b20","script":"seal","character":"笠","reading":"lì","description":"lì：(1)用竹篾或棕皮编制的遮阳挡雨的帽子斗（dǒu）～。竹～。草～。\n(2)竹篾编成的笠形覆盖物～盖。～覆。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笠"},{"id":"glyph-seal-7b25","script":"seal","character":"笥","reading":"sì","description":"sì：盛饭或衣物的方形竹器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笥"},{"id":"glyph-seal-7b26","script":"seal","character":"符","reading":"fú","description":"fú：(1)古代朝廷传达命令或征调兵将用的凭证虎～。～信。～节。\n(2)代表事物的标记、记号～号。音～。\n(3)相合～合。言行相～。\n(4)道士画的驱使鬼神的图形或线条～咒。护身～。\n(5)古代称祥瑞的征兆～瑞。～应（yìng）（指天降符瑞”，与人事相应）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-符"},{"id":"glyph-seal-7b28","script":"seal","character":"笨","reading":"bèn","description":"bèn：(1)不聪明～人。～拙。～伯（ａ．傻瓜，愚蠢的人；ｂ．肥大的人）。愚～。\n(2)不灵巧嘴～。～口拙舌。～鸟先飞。\n(3)粗重，费力气的～重。～活。粗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笨"},{"id":"glyph-seal-7b2a","script":"seal","character":"笪","reading":"dá","description":"dá：(1)一种用粗竹篾编成的像席的东西，晾晒粮食用。\n(2)牵船索。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笪"},{"id":"glyph-seal-7b2c","script":"seal","character":"第","reading":"dì","description":"dì：(1)次序～一。次～。等～。\n(2)科举考试及格的等次科～。及～。落～。\n(3)封建社会官僚贵族的大宅子宅～。府～。门～。进士～。\n(4)但运动有益于健康，～不宜过于剧烈。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-第"},{"id":"glyph-seal-7b2e","script":"seal","character":"笮","reading":"zé；zuó","description":"zuó：用竹篾拧成的索～桥（竹索桥）。\nzé：(1)铺在椽上瓦下的苇席或竹席。\n(2)压榨吏士渴乏，～马粪汁而饮之”。\n(3)装箭的竹器。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笮"},{"id":"glyph-seal-7b3a","script":"seal","character":"笺","reading":"jiān","description":"注释的文字\n中国古代写给帝王的书信\n⒈精美的或小幅的纸张手～。便～。信～。〈引〉书信来～已阅。\n⒉注释～注。\n⒊〈古〉一种文体，写给尊贵者的书信投～求归。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笺"},{"id":"glyph-seal-7b3c","script":"seal","character":"笼","reading":"lóng","description":"用竹片编成的盛物的器具\n桂枝为笼钩。\n饲养鸟、虫、家禽等的笼子\n⒉较大的箱子箱～。\n⒈用竹篾、木条或塑料等制做的盛物器或罩物器筷～。灯～。\n⒉养鸟、兽等的器具鸡～。鸟～子。蝈蝈～。\n⒊囚禁犯人的刑具囚～。\n⒋有盖用以蒸东西的器具蒸～。～屉。\n⒌将手放在袖筒里～着手。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笼"},{"id":"glyph-seal-7b3e","script":"seal","character":"笾","reading":"biān","description":"竹豆。古代用竹编成的食器,形状如豆,祭祀燕享时用来盛果实、干肉\n笾biān 1.古代祭祀和宴会时盛果脯的竹器，形状像木制的豆。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笾"},{"id":"glyph-seal-7b49","script":"seal","character":"等","reading":"děng","description":"děng：(1)古代指顿齐竹简（书）。\n(2)数量、程度相同，或地位一般高相～。平～。～于。～同。～值。～量齐观。\n(3)表示数量或程度的级别～级。～次。～第。～而下之。\n(4)特指台阶的级。\n(5)种，类这～事。\n(6)表示同一辈份的多数人我～。尔～。\n(7)表示列举未尽，或用于列举煞尾北京、上海～地。\n(8)候，待～候。～待。\n(9)待到～我写完。\n(10)同戥”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-等"},{"id":"glyph-seal-7b4b","script":"seal","character":"筋","reading":"jīn","description":"jīn：(1)肌肉的俗称～力。～肉。～疲力尽。\n(2)肌腱或附着在骨头上的韧带～骨。～道（道”读轻声）。蹄～。\n(3)可见的皮下静脉的俗称～络。～脉。青～暴露。\n(4)像筋的东西钢～。橡皮～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筋"},{"id":"glyph-seal-7b50","script":"seal","character":"筐","reading":"kuāng","description":"kuāng：竹子或柳条等编成的盛东西的器具～子。土～。抬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筐"},{"id":"glyph-seal-7b51","script":"seal","character":"筑","reading":"zhù","description":"捣土使坚实\n筑zhú 1.古弦乐器名。有五弦﹑十三弦﹑二十一弦三种说法。其形似筝，颈细而肩圆，弦下设柱。演奏时，左手按弦的一端，右手执竹尺击弦发音。战国时已有流行。 2.拾\n。 3.贵州省贵阳市的简称。明代称为贵筑司﹑贵筑乡，清代改为贵筑县◇因省称筑。\n筑zhù 1.捣土的杵。 2.捣土使坚实。 3.修建，建造。 4.居室;建筑物。 5.打，击。 6.填塞;装填。 7.拾取。 8.量名。 9.通\"祝\"。切断。 10.通\"妯\"。参见\"\n筑娌\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筑"},{"id":"glyph-seal-7b52","script":"seal","character":"筒","reading":"tǒng","description":"tǒng：(1)粗大的竹管。\n(2)较粗的中空而高的器物烟～。邮～。笔～。\n(3)衣服等的筒状部分袖～儿。靴～。～裙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筒"},{"id":"glyph-seal-7b54","script":"seal","character":"答","reading":"dá；dā","description":"dá：(1)回话，回复回～。对～。～辩。～复。～案。对～如流。\n(2)受了别人的好处，还（huán）报别人报～。～报。\n问；\ndā：义同（一），用于答应”答理”等词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-答"},{"id":"glyph-seal-7b56","script":"seal","character":"策","reading":"cè","description":"cè：(1)古代的一种马鞭子，头上有尖刺。\n(2)鞭打～马。鞭～。\n(3)激励，促进～动。～勉。\n(4)古代称连编好的竹简简～。\n(5)古代帝王对臣下封土、授爵或免官～命。～免。～封。\n(6)古代科举考试的一种文体～论。～问。\n(7)杖～杖。\n(8)中国数学上曾经用过的一种计算工具，形状与筹”相似。\n(9)计谋，主意，办法上～。献～。决～。政～。～划。束手无～。\n(10)书法用字名称，指仰横。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-策"},{"id":"glyph-seal-7b5a","script":"seal","character":"筚","reading":"bì","description":"泛指用竹子、荆条等织成的器物\n筚路蓝缕\n筚门圭窦\n筚 bì用荆条等编织的篱笆或其它遮挡物。\n【筚路蓝缕】驾驶柴车，穿着破烂衣服。形容创业的艰难。筚路柴车。蓝缕破衣服。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筚"},{"id":"glyph-seal-7b5d","script":"seal","character":"筝","reading":"zhēng","description":"zhēng：弦乐器，木制长形。古代十三或十六根弦，现为二十五根弦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筝"},{"id":"glyph-seal-7b60","script":"seal","character":"筠","reading":"jūn；yún","description":"yún：(1)竹子的青皮其在人也，如竹箭之有～也。”\n(2)竹子柴门空闭锁松～”。\njūn：〔～连〕地名，在中国四川省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筠"},{"id":"glyph-seal-7b6e","script":"seal","character":"筮","reading":"shì","description":"shì：古代用蓍草占卦龟为卜，策为～”。～仕（古人将出外做官，先占卦问吉凶◇称初次做官为筮仕”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筮"},{"id":"glyph-seal-7b71","script":"seal","character":"筱","reading":"xiǎo","description":"xiǎo：(1)细竹子。亦称箭竹”。\n(2)同小”，多用于人名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筱"},{"id":"glyph-seal-7b75","script":"seal","character":"筵","reading":"yàn；yán","description":"yán：(1)竹席～席。\n(2)酒席喜～。寿～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筵"},{"id":"glyph-seal-7b79","script":"seal","character":"筹","reading":"chóu","description":"壶矢。古代投壶用的签子,形如箭筩\n签筹;算筹\n算计\n策划\n①计数用具竹～。\n②谋划；筹划；计划～款、统～。\n【筹安会】袁世凯复辟帝制的御用团体。1915年8月由杨度、孙毓筠、严复、李燮和、胡瑛、刘师培等所谓'六君子'在北京发起成立。该会名义上以'研究君主、民主国体二者\n孰适于中国'为宗旨，实际公开进行复辟帝制活动。\n【筹划】想办法；定计划～工作。\n【筹算法】〈数〉我国古代用竹制的算筹记数并进行加、减、乘、除、开方等运算的方法。始于春秋时期，到明代被珠算代替。\n⒈计数的用具～码。\n⒉谋划，计划，计谋～备。熟～。统～安排。运～帷幄。一～莫展。\n⒊想办法收集～款。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筹"},{"id":"glyph-seal-7b7e","script":"seal","character":"签","reading":"qiān","description":"用简单的文字拟具意见\n粗粗地缝合起来\n引,导引\n下令征调\n刺;插\n旧时官府交给差役拘捕犯人的片状凭证,多用竹、木做成\n⒈亲笔署名或画上符号～名。～押。\n⒉简要的写出重点或意见～注。\n⒊旧时官府拘人的凭证朱～。火～。\n⒋用竹木等做成的细条或片状物牙～子。竹～儿。\n⒌用作标志的片条标～儿。书～。\n⒍迷信或赌博使用的片条求～祈神自欺欺人。\n⒎粗粗地缝合起来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-签"}];
